#!/usr/bin/env python3
"""Run from project root: python3 fix_terminal_ux.py"""
import base64, os, sys
if not os.path.exists("app"): sys.exit(1)
FILES = {
    "components/terminal/TerminalLayout.tsx": "",
    "components/BorrowPage.tsx": "",
}
for path, enc in FILES.items():
    d = os.path.dirname(path)
    if d: os.makedirs(d, exist_ok=True)
    content = base64.b64decode(enc).decode("utf-8")
    open(path, "w", encoding="utf-8", newline="\n").write(content)
    print(f"WRITTEN  {path}  ({len(content.splitlines())} lines)")
print("""
Fixes applied:
  1. Removed duplicate EN + CONNECT from TerminalLayout inner toolbar
  2. Removed LINK WALLET NODE button (main nav handles wallet connect)
  3. Removed useWalletModal / LanguageSelector / CompactWallet imports from TerminalLayout
  4. Mobile: abr-col-right hidden permanently (no more bleeding column)
  5. Loopscale CTA now goes to app.loopscale.com/vaults (not homepage)

Run:
  npm run build
  git add components/terminal/TerminalLayout.tsx components/BorrowPage.tsx
  git commit -m "fix: remove duplicate nav controls, fix mobile layout, Loopscale vaults URL"
  git push origin main
""")
